INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein integriertes System immer teurer als traditionelle Hardware ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kann langfristig Kosten senken"}, {"text": "Ja", "correct": false, "because": "Nicht immer teurer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, um Compute und Storage in einem System zu vereinen?', 3, '[{"text": "Hypervisor", "correct": true, "because": "Managed Virtualisierung"}, {"text": "Router", "correct": false, "because": "Nur Netzwerk"}, {"text": "Festplatte", "correct": false, "because": "Nur Speicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine kombinierte Infrastruktur?', 5, '[{"text": "Skalierbarkeit", "correct": true, "because": "Einfache Erweiterung"}, {"text": "Vereinfachte Verwaltung", "correct": true, "because": "Einheitliches Management"}, {"text": "Höhere Latenz", "correct": false, "because": "Nicht erwünscht"}, {"text": "Komplexere Hardware", "correct": false, "because": "Ziel ist Vereinfachung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sie nutzt Standard-Hardware. b) Sie ersetzt Cloud-Lösungen vollständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist kontextabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein System für Virtualisierung plane?', 4, '[{"text": "Netzwerkbandbreite", "correct": false, "because": "Wichtig für Performance"}, {"text": "Software-Definition", "correct": false, "because": "Kern der Lösung"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Systeme nur für kleine Firmen geeignet sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für große Unternehmen skalierbar"}, {"text": "Ja", "correct": false, "because": "Nicht auf Größe beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie wähle ich für eine einheitliche Plattform?', 3, '[{"text": "Software-defined Storage", "correct": true, "because": "Integriert Speicher"}, {"text": "Separate SAN", "correct": false, "because": "Nicht integriert"}, {"text": "Manuelle Verwaltung", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind in einer integrierten Lösung enthalten?', 5, '[{"text": "Compute", "correct": true, "because": "Rechenleistung"}, {"text": "Storage", "correct": true, "because": "Speicher"}, {"text": "Netzwerk", "correct": true, "because": "Verbindung"}, {"text": "Kaffeeautomat", "correct": false, "because": "Kein IT-Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) es weniger Hardware braucht und b) es immer schneller ist. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit hängt ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine kombinierte Infrastruktur?', 4, '[{"text": "Virtualisierung", "correct": false, "because": "Kernkomponente"}, {"text": "Einheitliches Management", "correct": false, "because": "Vereinfacht Betrieb"}, {"text": "Separate Silos", "correct": true, "because": "Widerspricht Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Hypervisor immer Teil davon?', 2, '[{"text": "Ja", "correct": true, "because": "Managed virtuelle Maschinen"}, {"text": "Nein", "correct": false, "because": "Standardkomponente"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Szenarien profitieren von einer integrierten Lösung?', 4, '[{"text": "VDI", "correct": true, "because": "Virtuelle Desktops"}, {"text": "Private Cloud", "correct": true, "because": "Skalierbare Umgebung"}, {"text": "Einzel-PC", "correct": false, "because": "Zu klein"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es keine Sicherheitsfunktionen hat. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Integriert Backup und Schutz"}, {"text": "Ja", "correct": false, "because": "Sicherheit ist enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer einheitlichen Plattform?', 3, '[{"text": "Kostensenkung", "correct": true, "because": "Weniger Hardware und Verwaltung"}, {"text": "Maximale Latenz", "correct": false, "because": "Nicht erwünscht"}, {"text": "Komplexität erhöhen", "correct": false, "because": "Ziel ist Vereinfachung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es skaliert durch Hinzufügen von Knoten. b) Es braucht spezielle Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nutzt Standard-Hardware"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Software in einer solchen Lösung?', 4, '[{"text": "Ressourcen virtualisieren", "correct": true, "because": "Abstrahiert Hardware"}, {"text": "Farben anpassen", "correct": false, "because": "Irrelevant"}, {"text": "Lautstärke regeln", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob es für Edge-Computing geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Kompakt und skalierbar"}, {"text": "Nein", "correct": false, "because": "Passt zu Edge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine kombinierte Lösung effektiv?', 5, '[{"text": "Einheitliches Management", "correct": true, "because": "Vereinfacht Betrieb"}, {"text": "Hohe Verfügbarkeit", "correct": true, "because": "Sichert Ausfallsicherheit"}, {"text": "Hohe Komplexität", "correct": false, "because": "Nicht erwünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt es traditionelle SANs komplett?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzt, nicht vollständig ersetzt"}, {"text": "Ja", "correct": false, "because": "Situationsabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt gut zu einer integrierten Plattform?', 4, '[{"text": "Datenbank-Cluster", "correct": true, "because": "Nutzt Skalierbarkeit"}, {"text": "Einzel-PC", "correct": false, "because": "Zu klein"}, {"text": "Manuelle Verwaltung", "correct": false, "because": "Widerspricht Konzept"}]');
